import pytest

from bedrock_protocol import v1001, v2168, v2225

VERSIONS = [v1001, v2168, v2225]

# generated by gophertunnel b8bd735:
# packet.ModalFormResponse{FormID: 300, ResponseData: protocol.Option([]byte("[true]"))}
RESPONSE = bytes.fromhex("ac0201065b747275655d00")

# generated by gophertunnel b8bd735:
# packet.ModalFormResponse{FormID: 1, CancelReason: protocol.Option(uint8(packet.ModalFormCancelReasonUserBusy))}
CANCELLED = bytes.fromhex("01000101")

# generated by gophertunnel b8bd735:
# packet.ModalFormResponse{FormID: 7, ResponseData: protocol.Option([]byte{}), CancelReason:
# protocol.Option(uint8(packet.ModalFormCancelReasonUserClosed))}
EMPTY_RESPONSE = bytes.fromhex("0701000100")

GOLDENS = (
    [
        pytest.param(
            v.ModalFormResponsePacket(form_id=300, json_response="[true]"),
            RESPONSE,
            id=f"{v.__name__.rpartition('.')[2]}-response",
        )
        for v in VERSIONS
    ]
    + [
        pytest.param(
            v.ModalFormResponsePacket(form_id=1, form_cancel_reason=v.ModalFormCancelReason.USER_BUSY),
            CANCELLED,
            id=f"{v.__name__.rpartition('.')[2]}-cancelled",
        )
        for v in VERSIONS
    ]
    + [
        pytest.param(
            v.ModalFormResponsePacket(
                form_id=7, json_response="", form_cancel_reason=v.ModalFormCancelReason.USER_CLOSED
            ),
            EMPTY_RESPONSE,
            id=f"{v.__name__.rpartition('.')[2]}-empty-response",
        )
        for v in VERSIONS
    ]
)


@pytest.mark.parametrize("version", VERSIONS, ids=lambda version: version.__name__.rpartition(".")[2])
def test_modal_form_response_is_packet_101(version):
    assert version.PACKETS[101] is version.ModalFormResponsePacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_modal_form_response_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_modal_form_response_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
